// Player weapon: compact alien plasma carbine in first-person view
const weapon=new THREE.Group();camera.add(weapon);weapon.position.set(.39,-.34,-.67);weapon.rotation.set(-.05,-.08,0);const gunBody=box(weapon,.19,.2,.62,alienMat,0,0,0);gunBody.castShadow=false;const barrel=box(weapon,.12,.12,.55,dark,0,.025,-.46);barrel.castShadow=false;const gunCore=box(weapon,.115,.045,.36,glowMat,0,.12,-.07);gunCore.castShadow=false;const gunGrip=box(weapon,.13,.24,.17,dark,0,-.17,.12);gunGrip.rotation.x=-.2;gunGrip.castShadow=false;const muzzleLight=new THREE.PointLight(0x55ffe0,0,6,2);muzzleLight.position.set(0,.04,-.85);weapon.add(muzzleLight);
const enemies=[],allies=[];let gameRunning=false,health=100,kills=0,sector=1,squadMode='ASSAULT',shotCooldown=0,spawnTimer=0,damageTimer=0,elapsed=0,walkBob=0,flashTimer=0;const keys={},raycaster=new THREE.Raycaster();let yaw=0,pitch=0,locked=false,fireHeld=false,fireInterval=0;
function makeHumanoid(isAlly=false){const group=new THREE.Group();const armor=isAlly?mat(0x243b3d,.42,.65):mat(Math.random()<.25?0x4c5758:0x39464a,.72,.28);const skin=mat(isAlly?0x667c69:0x718078,.9);box(group,.57,.75,.32,armor,0,1.12,0);box(group,.39,.39,.36,skin,0,1.74,0);const eyeMat=new THREE.MeshBasicMaterial({color:isAlly?0x70ffe3:0xff554b});for(const s of [-1,1]){const eye=new THREE.Mesh(new THREE.SphereGeometry(.055,8,8),eyeMat);eye.position.set(s*.105,1.79,-.185);group.add(eye);const arm=box(group,.21,.65,.24,armor,s*.4,1.15,-.02);arm.rotation.z=s*.13;const leg=box(group,.23,.7,.27,dark,s*.17,.38,.015);leg.position.y=.36}const headTop=box(group,.24,.08,.23,dark,0,1.99,.01);const backpack=box(group,.34,.45,.2,dark,0,1.22,.25);backpack.castShadow=true;const rifle=box(group,.1,.1,.62,isAlly?dark:mat(0x2a3234,.4,.7),.28,1.12,-.24);const rifleCore=box(group,.055,.04,.32,isAlly?glowMat:warmMat,.28,1.18,-.34);group.userData={isAlly,hp:isAlly?1:2,alive:true,fire:1+Math.random()*1.6,phase:Math.random()*6,home:null};return group}
function spawnEnemy(x,z){const e=makeHumanoid(false);e.position.set(x,0,z);e.userData.home=e.position.clone();scene.add(e);enemies.push(e);return e}
function spawnAlly(x,z){const e=makeHumanoid(true);e.position.set(x,0,z);e.userData.home=e.position.clone();scene.add(e);allies.push(e);return e}
const startSpawns=[[-9,-17],[9,-19],[-5,-25],[7,-33],[-10,-38],[11,-43],[-4,-48],[5,-55]];
function resetGame(){for(const e of [...enemies,...allies])scene.remove(e);enemies.length=0;allies.length=0;health=100;kills=0;sector=1;squadMode='ASSAULT';elapsed=0;spawnTimer=0;camera.position.set(0,1.72,8);yaw=0;pitch=0;for(const p of startSpawns)spawnEnemy(...p);spawnAlly(-1.5,9);spawnAlly(1.5,10);spawnAlly(0,11);updateHud();$('#end').classList.add('hidden');$('#intro').classList.add('hidden');$('#hud').style.display='block';gameRunning=true;initAudio();if(innerWidth>750)renderer.domElement.requestPointerLock?.();}
function updateHud(){$('#enemyCount').textContent=String(enemies.filter(e=>e.userData.alive).length).padStart(2,'0');$('#sector').textContent=String(sector).padStart(2,'0');$('#squadCount').textContent=String(allies.filter(a=>a.userData.alive).length).padStart(2,'0');$('#healthNum').textContent=Math.ceil(health);$('#healthFill').style.width=health+'%';$('#commandMode').textContent=squadMode;$('#squadMode').textContent=squadMode==='HOLD'?'HOLDING POSITION':squadMode==='RETREAT'?'FALLING BACK':'ADVANCING';$('#objective').textContent=enemies.filter(e=>e.userData.alive).length?'BREAK THE DEFENSE LINE':'SECURE THE BEACON';}
function command(n){if(!gameRunning)return;squadMode=n==='1'?'HOLD':n==='2'?'ASSAULT':'RETREAT';const word={1:'ZOB!',2:'TOBALSO!',3:'YOBOK!'}[n],sub={1:'SQUAD HOLDING POSITION',2:'ASSAULT ORDER CONFIRMED',3:'SQUAD FALLING BACK'}[n];$('#toast').innerHTML=`${word}<small>${sub}</small>`;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),1250);playTone(n==='2'?170:120,n==='1'?'square':'sawtooth',.16,.045);updateHud()}
let audioCtx=null,master=null;function initAudio(){if(audioCtx){audioCtx.resume?.();return}try{audioCtx=new (window.AudioContext||window.webkitAudioContext)();master=audioCtx.createGain();master.gain.value=.22;master.connect(audioCtx.destination);const osc=audioCtx.createOscillator(),gain=audioCtx.createGain();osc.type='sawtooth';osc.frequency.value=47;gain.gain.value=.026;const filter=audioCtx.createBiquadFilter();filter.type='lowpass';filter.frequency.value=110;osc.connect(filter);filter.connect(gain);gain.connect(master);osc.start()}catch(e){}}
function playTone(freq,type='sawtooth',duration=.12,volume=.07){if(!audioCtx)return;const o=audioCtx.createOscillator(),g=audioCtx.createGain();o.type=type;o.frequency.setValueAtTime(freq,audioCtx.currentTime);o.frequency.exponentialRampToValueAtTime(Math.max(40,freq*.48),audioCtx.currentTime+duration);g.gain.setValueAtTime(volume,audioCtx.currentTime);g.gain.exponentialRampToValueAtTime(.001,audioCtx.currentTime+duration);o.connect(g);g.connect(master);o.start();o.stop(audioCtx.currentTime+duration)}
function playShot(){if(!gameRunning||shotCooldown>0)return;shotCooldown=.22;flashTimer=.085;muzzleLight.intensity=28;playTone(220,'sawtooth',.14,.11);setTimeout(()=>playTone(95,'triangle',.11,.07),25);weapon.position.z=-.58;setTimeout(()=>{weapon.position.z=-.67},65);raycaster.setFromCamera(new THREE.Vector2(0,0),camera);raycaster.far=65;const candidates=[];for(const e of enemies)if(e.userData.alive){const meshes=[];e.traverse(o=>{if(o.isMesh)meshes.push(o)});candidates.push(...meshes)}const hits=raycaster.intersectObjects(candidates,false);if(hits.length){let target=hits[0].object;while(target.parent&&!target.userData.alive)target=target.parent;if(target.userData.alive&&!target.userData.isAlly){target.userData.hp--;target.position.x+=0;$('#hitmarker').classList.add('show');setTimeout(()=>$('#hitmarker').classList.remove('show'),90);if(target.userData.hp<=0){target.userData.alive=false;target.visible=false;kills++;playTone(410,'triangle',.08,.06);updateHud();checkProgress()}}}}
function checkProgress(){const alive=enemies.filter(e=>e.userData.alive).length;if(alive===0){if(sector===1){sector=2;$('#objective').textContent='HOLD THE LANDING ZONE';spawnTimer=4.5;$('#toast').innerHTML='SECTOR 01 CLEAR<small>INCOMING HOSTILES DETECTED</small>';$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),2200);updateHud()}else finishGame(true)}}
function finishGame(win){gameRunning=false;document.exitPointerLock?.();$('#hud').style.display='none';$('#end').classList.remove('hidden');$('#endTitle').innerHTML=win?'SECTOR <span>SECURED</span>':'MISSION <span>FAILED</span>';$('#endCopy').textContent=win?'The beacon is yours. Your people have their first foothold on Earth. The invasion begins.':'The human defense line held this time. Vanguard Prime, regroup—the landing is not over.';$('#endResult').textContent=`DEFENDERS NEUTRALIZED · ${String(kills).padStart(2,'0')}`}
function hurt(amount){health=clamp(health-amount,0,100);damageTimer=.2;$('#damageFlash').classList.add('show');setTimeout(()=>$('#damageFlash').classList.remove('show'),180);updateHud();playTone(72,'square',.18,.08);if(health<=0)finishGame(false)}
function enemyFire(e){if(!gameRunning)return;const start=e.position.clone().add(new THREE.Vector3(0,1.3,0)),end=camera.position.clone();const dist=start.distanceTo(end);if(dist<23&&Math.random()<.72){const g=new THREE.BufferGeometry().setFromPoints([start,end]);const line=new THREE.Line(g,new THREE.LineBasicMaterial({color:0xff674f,transparent:true,opacity:.8}));scene.add(line);setTimeout(()=>scene.remove(line),80);hurt(3+Math.random()*5)}else{const target=camera.position.clone();target.x+=(Math.random()-.5)*3;target.z+=(Math.random()-.5)*2;const g=new THREE.BufferGeometry().setFromPoints([start,target]);const line=new THREE.Line(g,new THREE.LineBasicMaterial({color:0xffa45d,transparent:true,opacity:.7}));scene.add(line);setTimeout(()=>scene.remove(line),100)}}
function allyFire(a){const alive=enemies.filter(e=>e.userData.alive);if(!alive.length)return;let target=alive.reduce((best,e)=>a.position.distanceTo(e.position)<a.position.distanceTo(best.position)?e:best,alive[0]);const from=a.position.clone().add(new THREE.Vector3(0,1.35,0)),to=target.position.clone().add(new THREE.Vector3(0,1.4,0));const g=new THREE.BufferGeometry().setFromPoints([from,to]);const line=new THREE.Line(g,new THREE.LineBasicMaterial({color:0x55ffe0,transparent:true,opacity:.65}));scene.add(line);setTimeout(()=>scene.remove(line),65);if(Math.random()<.42){target.userData.hp--;if(target.userData.hp<=0){target.userData.alive=false;target.visible=false;kills++;updateHud();checkProgress()}}}

